const envelope = items[0]?.json;
const raw = envelope && typeof envelope === 'object' && !Array.isArray(envelope)
  ? (envelope.body ?? envelope)
  : null;
const executionId = String($execution?.id ?? Date.now());
const corsHeaders = {
  'Access-Control-Allow-Origin': 'http://localhost:5173',
  'Vary': 'Origin',
  'Content-Type': 'application/json'
};
const nonEmpty = value => typeof value === 'string' && value.trim().length > 0;
const plainObject = value => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const validHttpUrl = value => nonEmpty(value) && /^https?:\/\/[^\s]+$/i.test(value.trim());

const errors = [];
if (!plainObject(raw)) errors.push('Request body must be a JSON object.');
const intake = plainObject(raw?.intake) ? raw.intake : null;
if (!intake) {
  errors.push('intake is required.');
} else {
  if (!nonEmpty(intake.organization_name)) errors.push('intake.organization_name is required.');
  if (!validHttpUrl(intake.website)) errors.push('intake.website must be a valid HTTP(S) URL.');
  if (!nonEmpty(intake.country)) errors.push('intake.country is required.');
}
const request = {
  ...(plainObject(raw) ? raw : {}),
  contract_version: nonEmpty(raw?.contract_version) ? raw.contract_version : '1.0',
  mode: 'live',
  correlation_id: nonEmpty(raw?.correlation_id) ? raw.correlation_id : `CORR-${executionId}`,
  run_id: nonEmpty(raw?.run_id) ? raw.run_id : `RUN-WEBHOOK-${executionId}`,
  intake: intake ?? {}
};
return [{ json: { valid: errors.length === 0, errors, request, cors_headers: corsHeaders } }];

const request = items[0].json.request;
const intake = request.intake;
const countryNames = { US: 'United States' };
const country = countryNames[intake.country] || intake.country;
return [{ json: {
  organization_name: intake.organization_name,
  website: intake.website,
  country,
  query: `${intake.organization_name} annual report audited financial statements revenue funding grants donations impact outcomes`,
  correlation_id: request.correlation_id,
  transport_intake: intake,
  run_context: {
    run_id: request.run_id || `RUN-PROJECT3-${Date.now()}`,
    organization: { name: intake.organization_name, website: intake.website, country },
    current_challenge: intake.current_challenge,
    uploaded_document_refs: intake.uploaded_document_refs,
    research_window: intake.research_window,
    status: 'created',
    started_at: new Date().toISOString(),
    errors: []
  }
} }];

const output = items[0]?.json;
const validated = $('VALIDATE__TRANSPORT_REQUEST').first().json;
const request = validated.request;
const runId = output?.run_context?.run_id || request.run_id || `RUN-WEBHOOK-${$execution.id}`;
const base = { contract_version: '1.0', correlation_id: request.correlation_id, run_id: runId, demo: false };
const isObject = value => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const rows = (value) => Array.isArray(value) ? value : [];
const sources = rows(output?.paola?.sources);
const evidence = rows(output?.paola?.evidence);
const findings = rows(output?.paola?.findings);
const unknowns = rows(output?.paola?.unknowns);
const contradictions = rows(output?.paola?.contradictions);
const sourceIds = new Set(sources.map(source => source?.source_id));
const evidenceIds = new Set(evidence.map(item => item?.evidence_id));
const unique = values => values.length === new Set(values).size;
const evidenceTraceValid = evidence.every(item => isObject(item) && Array.isArray(item.source_ids) && item.source_ids.every(id => sourceIds.has(id)));
const findingTraceValid = findings.every(item => isObject(item) && Array.isArray(item.evidence_ids) && item.evidence_ids.length > 0 && item.evidence_ids.every(id => evidenceIds.has(id)));
const complete = isObject(output) && ['demo_ready', 'partial_demo'].includes(output.controlled_state)
  && sources.length > 0 && evidence.length > 0 && findings.length > 0
  && unique(sources.map(source => source.source_id)) && unique(evidence.map(item => item.evidence_id)) && unique(findings.map(item => item.finding_id))
  && evidenceTraceValid && findingTraceValid;
if (!complete) {
  return [{ json: {
    http_status: 422,
    response: { ...base, status: 'needs_evidence', message: 'Evidence is required before this analysis can run.', error: { code: 'evidence_required' } }
  } }];
}
return [{ json: {
  http_status: 200,
  response: {
    ...base,
    status: 'completed',
    message: 'Diagnostic prepared from the verified end-to-end workflow.',
    completed_at: new Date().toISOString(),
    data: {
      intake: request.intake,
      sources, evidence, findings, unknowns, contradictions,
      rag_metadata: {
        upstream_workflow: 'DEV_PROJECT3_END_TO_END',
        controlled_state: output.controlled_state,
        trace: output.trace || {},
        paola_states: output.paola_states || {}
      }
    }
  }
} }];

const validated = $('VALIDATE__TRANSPORT_REQUEST').first().json;
const request = validated.request;
return [{ json: { response: {
  contract_version: '1.0', status: 'error', correlation_id: request.correlation_id,
  run_id: request.run_id || `RUN-WEBHOOK-${$execution.id}`, demo: false,
  message: 'The end-to-end diagnostic workflow did not complete.', error: { code: 'upstream_failure' }
} } }];
